=head2 Google::Cloud::Alloydb::V1beta::Resources::Database

Message describing Database object.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->name() >> / C<< $msg->name($value) >>

